package com.chondrimaishrat.elearning.tutoring; import com.chondrimaishrat.elearning.user.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.*; import java.util.*;
@Service public class TutoringService {private final TutoringSlotRepository slots;public TutoringService(TutoringSlotRepository s){slots=s;} public List<TutoringSlot> available(){return slots.findByStatusOrderByStartsAtAsc(SlotStatus.AVAILABLE);}@Transactional public void create(UserAccount i,LocalDateTime start,LocalDateTime end,String link){if(i.getRole()!=UserRole.INSTRUCTOR||!end.isAfter(start))throw new IllegalArgumentException("Enter a valid tutoring time range.");slots.save(new TutoringSlot(i,start,end,link));}@Transactional public void book(UserAccount student,Long id){if(student.getRole()!=UserRole.STUDENT)throw new IllegalArgumentException("Only students can book tutoring.");TutoringSlot slot=slots.lockById(id).orElseThrow(()->new IllegalArgumentException("Slot not found."));slot.book(student);}}
